const config = $input.all()[0].json;
return [{
  json: {
    loginUrl: `${config.atmoBaseUrl}${config.atmoLoginPath}`,
    generatedAt: config.generatedAt,
  }
}];

const checkedAt = new Date().toISOString();
const config = $items('Set Connector Config')[0].json;
const inputItems = $input.all();
if (!inputItems.length) {
  return [{ json: { authOk: false, classification: 'CREDENTIALS_BLOCKED', httpStatus: 0, checkedAt, error: 'No response reached the Atmo login node' } }];
}
const raw = inputItems[0].json || {};
const status = Number(raw.statusCode || 0);
const bodyText = String(raw.body || '');

if (status === 401 || status === 403) {
  return [{ json: { authOk: false, classification: 'CREDENTIALS_BLOCKED', httpStatus: status, checkedAt, error: 'Atmo login rejected the bound credential (401/403). Never logging the response body.' } }];
}
if (!status || status < 200 || status >= 300 || !bodyText) {
  return [{ json: { authOk: false, classification: 'CONNECTOR_LOGIC_FAILED', httpStatus: status || 0, checkedAt, error: 'Atmo login failed or returned an empty body' } }];
}

let parsed;
try {
  parsed = JSON.parse(bodyText);
} catch (err) {
  return [{ json: { authOk: false, classification: 'CONNECTOR_LOGIC_FAILED', httpStatus: status, checkedAt, error: 'Atmo login response was not valid JSON: ' + err.message } }];
}

const token = parsed && parsed.token;
if (!token || typeof token !== 'string') {
  return [{ json: { authOk: false, classification: 'CONNECTOR_LOGIC_FAILED', httpStatus: status, checkedAt, error: 'Atmo login succeeded but no token field was present in the response shape (expected response.token)' } }];
}

// The token is passed downstream via the item field for use in the next
// HTTP nodes' headers only. It is never written into any output payload
// and never logged/printed by this or any later node.
return [{ json: { authOk: true, classification: 'ok', httpStatus: status, checkedAt, bearerToken: token } }];

const config = $items('Set Connector Config')[0].json;
const auth = $input.all()[0].json;
const aasqaCodes = JSON.parse(config.aasqaCodesJson);
const items = [];
for (const aasqa of aasqaCodes) {
  const indexParams = new URLSearchParams({
    format: 'geojson',
    date: config.generatedAt.slice(0, 10),
    date_historique: config.generatedAt.slice(0, 10),
    aasqa,
  });
  items.push({
    json: {
      requestKind: 'indices',
      aasqa,
      url: `${config.atmoBaseUrl}${config.atmoIndicesPath}?${indexParams.toString()}`,
      bearerToken: auth.bearerToken,
      generatedAt: config.generatedAt,
    }
  });
  const episodeParams = new URLSearchParams({ format: 'geojson', aasqa });
  items.push({
    json: {
      requestKind: 'episodes',
      aasqa,
      url: `${config.atmoBaseUrl}${config.atmoEpisodesPath}?${episodeParams.toString()}`,
      bearerToken: auth.bearerToken,
      generatedAt: config.generatedAt,
    }
  });
}
return items;

// ATMO index levels 1-6, preserving the exact repo-verified official palette
// (scripts/lib/atmo-map-layer.mjs) and the severity/label mapping used by
// scripts/fetch-atmo-france.mjs. Do not alter these values.
const levels = {
  1: { severity: 'green', labelEn: 'Good', labelFr: 'Bon', color: '#50f0e6', explanation: null },
  2: { severity: 'green', labelEn: 'Fair', labelFr: 'Moyen', color: '#50ccaa', explanation: null },
  3: { severity: 'yellow', labelEn: 'Degraded', labelFr: 'D\u00e9grad\u00e9', color: '#f0e641', explanation: (zone) => `ATMO reports degraded (d\u00e9grad\u00e9) air quality near ${zone}; sensitive riders may notice effects and should moderate intense efforts.` },
  4: { severity: 'orange', labelEn: 'Bad', labelFr: 'Mauvais', color: '#ff5050', explanation: (zone) => `ATMO reports bad (mauvais) air quality near ${zone}; pollution may affect all riders, so limit prolonged hard efforts today.` },
  5: { severity: 'red', labelEn: 'Very bad', labelFr: 'Tr\u00e8s mauvais', color: '#960032', explanation: (zone) => `ATMO reports very bad (tr\u00e8s mauvais) air quality near ${zone}; health effects are likely, so avoid strenuous outdoor exertion.` },
  6: { severity: 'red', labelEn: 'Extremely bad', labelFr: 'Extr\u00eamement mauvais', color: '#7d2181', explanation: (zone) => `ATMO reports extremely bad (extr\u00eamement mauvais) air quality near ${zone}; serious health risk, avoid outdoor exertion until conditions improve.` },
};

const config = $items('Set Connector Config')[0].json;
const requestMeta = $items('Build Atmo Data Requests');
const inputItems = $input.all();
const checkedAt = new Date().toISOString();
const indexDate = config.generatedAt.slice(0, 10);
const corridorKm = Number(config.corridorKm);

let okResponses = 0;
let failedResponses = 0;
const indexRecords = [];

for (let i = 0; i < inputItems.length; i++) {
  const meta = (requestMeta[i] && requestMeta[i].json) || {};
  if (meta.requestKind !== 'indices') continue;
  const raw = inputItems[i].json || {};
  const status = Number(raw.statusCode || 0);
  const bodyText = String(raw.body || '');
  if (!status || status < 200 || status >= 300 || !bodyText) { failedResponses++; continue; }
  let body;
  try { body = JSON.parse(bodyText); } catch (err) { failedResponses++; continue; }
  const features = Array.isArray(body?.features) ? body.features : [];
  okResponses++;
  for (const feature of features) {
    const props = feature?.properties ?? {};
    const longitude = Number(props.x_wgs84);
    const latitude = Number(props.y_wgs84);
    const codeQual = Number(props.code_qual);
    if (!Number.isFinite(longitude) || !Number.isFinite(latitude) || !levels[codeQual]) continue;
    indexRecords.push({
      codeQual,
      libQual: props.lib_qual || levels[codeQual].labelEn,
      zone: props.lib_zone || props.code_zone || 'route corridor',
      codeZone: props.code_zone ?? null,
      aasqa: props.aasqa ?? meta.aasqa ?? null,
      atmoSource: props.source ?? null,
      dateEch: props.date_ech ?? indexDate,
      dateMaj: props.date_maj ?? null,
      longitude,
      latitude,
    });
  }
}

function toObservation(record, rideDay, distanceFromRouteKm) {
  const level = levels[record.codeQual];
  const title = `${level.labelEn} air quality (${record.libQual}) near ${record.zone}.`;
  const explanation = level.explanation ? level.explanation(record.zone) : null;
  return {
    json: {
      recordKind: 'atmoIndex',
      externalId: `atmo-france-rd${rideDay}-${record.dateEch}`,
      sourceId: 'atmo-france',
      category: 'atmo_index',
      severity: level.severity,
      status: 'confirmed',
      title,
      nearestPlace: record.zone,
      rideDay,
      routeSegment: `Ride day ${rideDay}`,
      longitude: record.longitude,
      latitude: record.latitude,
      distanceFromRouteKm: Number(distanceFromRouteKm.toFixed(3)),
      routeInfluenceConfirmed: true,
      startTime: /^\d{4}-\d{2}-\d{2}$/.test(String(record.dateEch)) ? `${record.dateEch}T12:00:00.000Z` : checkedAt,
      expectedEndTime: null,
      checkedAt,
      sourceUrl: config.sourceUrl,
      summary: `ATMO index ${record.codeQual} of 6 (${record.libQual}) for ${record.zone}, the worst reading within ${corridorKm} km of this ride day.`,
      atmoIndex: record.codeQual,
      atmoIndexLabelEn: level.labelEn,
      atmoIndexLabelFr: level.labelFr,
      atmoIndexColor: level.color,
      ...(explanation ? { statusTitle: title, statusExplanation: explanation } : {}),
      statusSource: { name: 'ATMO France', url: config.sourceUrl, official: true, checkedAt, sourceLanguage: 'fr', translationMethod: 'condensed_official_source' },
      whyItMatters: 'The ATMO index is the official French air-quality scale; poor air affects breathing during sustained cycling effort.',
      recommendedAction: level.severity === 'green' ? 'No air-quality action needed; the ATMO index is favourable for this ride day.' : 'Check the ATMO France map for the affected communes and moderate effort or adjust timing accordingly.',
      raw: { aasqa: record.aasqa, codeZone: record.codeZone, codeQual: record.codeQual, dateEch: record.dateEch, dateMaj: record.dateMaj, atmoSource: record.atmoSource },
    }
  };
}

// Route-corridor matching (nearest ride-day route segment) is only
// meaningful with public/cdm-ride-days.geojson geometry, which this Code
// node does not have inline (see Output Contract for why route-geometry
// intersection is out of scope for this pass). Records are emitted as
// corridor zone candidates keyed by AASQA/zone rather than a specific ride
// day, matching the 'do not invent geometries or route-zone intersections'
// instruction; ride-day assignment stays with the existing Node.js
// fetch-atmo-france.mjs pipeline until route geometry is wired into n8n.
const zoneRecords = indexRecords.map((record, idx) => toObservation(record, null, 0)[0].json).map((json, idx) => ({ json: { ...json, externalId: `atmo-france-zone-${json.raw.codeZone || idx}-${json.raw.dateEch}`, rideDay: null, routeSegment: null, distanceFromRouteKm: null } }));

const healthStatus = failedResponses > 0 && okResponses === 0 ? 'failed' : (failedResponses > 0 ? 'degraded' : 'ok');
const sourceHealth = {
  json: {
    recordKind: 'sourceHealth',
    sourceId: 'atmo-france',
    sourceName: 'Atmo France / Atmo Data',
    status: healthStatus,
    fetchedAt: checkedAt,
    staleAfterMinutes: Number(config.staleAfterMinutes),
    httpStatus: okResponses > 0 ? 200 : 0,
    recordCount: zoneRecords.length,
    errors: healthStatus === 'failed' ? ['All Atmo index requests failed or returned invalid data'] : [],
    warnings: failedResponses > 0 && okResponses > 0 ? [`${failedResponses} of ${okResponses + failedResponses} Atmo index requests failed`] : [],
  }
};

return [...zoneRecords, sourceHealth];

const config = $items('Set Connector Config')[0].json;
const departments = JSON.parse(config.departmentsJson);
const departmentByCode = new Map(departments.map((d) => [d.code, d]));
const requestMeta = $items('Build Atmo Data Requests');
const inputItems = $input.all();
const checkedAt = new Date().toISOString();
const indexDate = config.generatedAt.slice(0, 10);

let okResponses = 0;
let failedResponses = 0;
const episodeRecords = [];

for (let i = 0; i < inputItems.length; i++) {
  const meta = (requestMeta[i] && requestMeta[i].json) || {};
  if (meta.requestKind !== 'episodes') continue;
  const raw = inputItems[i].json || {};
  const status = Number(raw.statusCode || 0);
  const bodyText = String(raw.body || '');
  if (!status || status < 200 || status >= 300 || !bodyText) { failedResponses++; continue; }
  let body;
  try { body = JSON.parse(bodyText); } catch (err) { failedResponses++; continue; }
  const features = Array.isArray(body?.features) ? body.features : [];
  okResponses++;
  for (const feature of features) {
    const props = feature?.properties ?? {};
    const etat = String(props.etat ?? '').toUpperCase();
    if (!etat || etat.includes('PAS DE DEPASSEMENT')) continue;
    const department = departmentByCode.get(String(props.code_zone ?? ''));
    if (!department || !department.rideDays.length) continue;
    const dateEch = String(props.date_ech ?? indexDate);
    if (dateEch < indexDate) continue;
    const isAlert = etat.includes('ALERTE');
    const severity = isAlert ? 'red' : 'orange';
    const stateEn = isAlert ? 'alert-level' : 'information-level';
    const pollutant = props.lib_pol || 'pollution';
    const dayWord = dateEch > indexDate ? 'tomorrow' : 'today';
    for (const rideDay of department.rideDays) {
      const title = `${isAlert ? 'Alert' : 'Information'} pollution episode (${pollutant}) in ${department.name} (${dayWord}).`;
      episodeRecords.push({
        json: {
          recordKind: 'pollutionEpisode',
          externalId: `atmo-france-episode-${props.code_zone}-${props.code_pol ?? pollutant}-${dateEch}-rd${rideDay}`,
          sourceId: 'atmo-france',
          category: 'pollution_episode',
          severity,
          status: dateEch > indexDate ? 'forecast' : 'confirmed',
          title,
          nearestPlace: department.name,
          departmentCode: department.code,
          departmentName: department.name,
          rideDay,
          routeSegment: `Ride day ${rideDay}`,
          distanceFromRouteKm: null,
          routeInfluenceConfirmed: true,
          startTime: /^\d{4}-\d{2}-\d{2}$/.test(dateEch) ? `${dateEch}T12:00:00.000Z` : checkedAt,
          expectedEndTime: null,
          checkedAt,
          sourceUrl: config.sourceUrl,
          summary: `ATMO France reports an active ${stateEn} pollution episode for ${pollutant} in ${department.name} (${dateEch}).`,
          statusTitle: title,
          statusExplanation: isAlert ? `ATMO France declares an alert-level ${pollutant} pollution episode in ${department.name}; prefecture measures may apply, avoid strenuous outdoor exertion.` : `ATMO France declares an information-level ${pollutant} pollution episode in ${department.name}; sensitive riders should reduce intense and prolonged efforts.`,
          statusSource: { name: 'ATMO France', url: config.sourceUrl, official: true, checkedAt, sourceLanguage: 'fr', translationMethod: 'condensed_official_source' },
          whyItMatters: 'An official pollution episode means measured or forecast exceedance of regulatory thresholds across this department.',
          recommendedAction: 'Check ATMO France and prefecture advisories for the affected department before extended riding.',
          raw: { aasqa: props.aasqa, codeZone: props.code_zone, etat: props.etat, pollutant: props.lib_pol, codePol: props.code_pol, dateEch, dateMaj: props.date_maj ?? null },
        }
      });
    }
  }
}

const healthStatus = failedResponses > 0 && okResponses === 0 ? 'failed' : (failedResponses > 0 ? 'degraded' : 'ok');
const summaryRecord = {
  json: {
    recordKind: 'pollutionEpisodeSummary',
    activeEpisodeCount: episodeRecords.length,
    zeroActiveEpisodes: episodeRecords.length === 0,
    checkedAt,
  }
};
const sourceHealth = {
  json: {
    recordKind: 'sourceHealth',
    sourceId: 'atmo-france-episodes',
    sourceName: 'Atmo France / Atmo Data (pollution episodes)',
    status: healthStatus,
    fetchedAt: checkedAt,
    staleAfterMinutes: Number(config.staleAfterMinutes),
    httpStatus: okResponses > 0 ? 200 : 0,
    recordCount: episodeRecords.length,
    errors: healthStatus === 'failed' ? ['All Atmo episode requests failed or returned invalid data'] : [],
    warnings: failedResponses > 0 && okResponses > 0 ? [`${failedResponses} of ${okResponses + failedResponses} Atmo episode requests failed`] : [],
  }
};

return [...episodeRecords, summaryRecord, sourceHealth];

// Corridor zone records are derived only from the Atmo index zone records
// already normalized above (props.lib_zone / code_zone / aasqa), matching
// the 'do not invent geometries or route-zone intersections' rule -- no
// route-geometry file is embedded in this Code node. Each corridor zone
// record is a compatibility-shaped candidate for public/data/atmo-air-quality-map.json.
const config = $items('Set Connector Config')[0].json;
const checkedAt = new Date().toISOString();
const indexZones = $input.all().map((i) => i.json || {}).filter((r) => r.recordKind === 'atmoIndex');

const zones = indexZones.map((r) => ({
  json: {
    recordKind: 'corridorZone',
    id: r.externalId,
    zoneName: r.nearestPlace,
    longitude: r.longitude,
    latitude: r.latitude,
    codeQual: r.atmoIndex,
    labelFr: r.atmoIndexLabelFr,
    labelEn: r.atmoIndexLabelEn,
    color: r.atmoIndexColor,
    checkedAt: r.checkedAt,
    sourceName: `Atmo France / ${r.raw?.atmoSource || r.raw?.aasqa || 'regional AASQA'}`,
    sourceUrl: r.sourceUrl,
  }
}));

return zones.length ? zones : [{ json: { recordKind: 'corridorZone', zeroZones: true, checkedAt } }];

const config = $items('Set Connector Config')[0].json;
const allInputs = [];
for (const name of ['Normalize Atmo Index Records', 'Normalize Pollution Episode Records', 'Build Corridor Zone Records']) {
  try {
    allInputs.push(...$items(name).map((i) => i.json || {}));
  } catch (err) {
    // Node may not have produced items on a given branch; treated below.
  }
}

function validIso(v) { return !v || !Number.isNaN(Date.parse(v)); }
function looksLikeSecret(v) {
  if (typeof v !== 'string') return false;
  return /^[A-Za-z0-9_-]{24,}$/.test(v) && !/^https?:\/\//.test(v);
}
const severityEnum = ['green', 'yellow', 'orange', 'red'];
const sourceHealthRequired = ['sourceId', 'sourceName', 'status', 'fetchedAt', 'staleAfterMinutes', 'httpStatus', 'recordCount', 'errors', 'warnings'];
const recordRequiredFields = ['externalId', 'sourceId', 'category', 'severity', 'status', 'title', 'checkedAt'];

const errors = [];
const warnings = [];

if (!config.connectorId) errors.push('Missing connectorId in Set Connector Config');
if (!config.connectorNumber) errors.push('Missing connectorNumber in Set Connector Config');
if (!config.workflowVersion) errors.push('Missing workflowVersion in Set Connector Config');
if (!validIso(config.generatedAt)) errors.push('Missing or invalid generatedAt in Set Connector Config');
if (!config.outputDirectory || !config.outputDirectory.startsWith('/files/cdm-status-output')) {
  errors.push('Forbidden or missing output directory: expected /files/cdm-status-output');
}
if (!config.attributionText) errors.push('Missing attribution text (ODbL requirement)');

const fullText = JSON.stringify(allInputs);
if (/bearer\s+[A-Za-z0-9_\-.]{20,}/i.test(fullText)) errors.push('Possible bearer token leaked into merged output records');
if (fullText.toLowerCase().includes('atmo_france_username') || fullText.toLowerCase().includes('atmo_france_password')) {
  errors.push('Possible hardcoded credential name/value leaked into merged output records');
}

let sawSourceHealth = false;
for (const r of allInputs) {
  if (r.recordKind === 'sourceHealth') {
    sawSourceHealth = true;
    for (const field of sourceHealthRequired) {
      if (r[field] === undefined || r[field] === null) errors.push(`sourceHealth ${r.sourceId || 'unknown'} missing ${field}`);
    }
    if (!validIso(r.fetchedAt)) errors.push(`sourceHealth ${r.sourceId} has invalid fetchedAt`);
    if (!['ok', 'degraded', 'failed', 'stale', 'credentials_blocked'].includes(r.status)) errors.push(`sourceHealth ${r.sourceId} has invalid status enum: ${r.status}`);
    continue;
  }
  if (r.recordKind === 'atmoIndex' || r.recordKind === 'pollutionEpisode') {
    for (const field of recordRequiredFields) {
      if (r[field] === undefined || r[field] === null || r[field] === '') errors.push(`${r.recordKind}/${r.externalId || 'unknown'}: missing required field ${field}`);
    }
    if (r.severity && !severityEnum.includes(r.severity)) errors.push(`${r.recordKind}/${r.externalId}: invalid severity enum ${r.severity}`);
    if (!validIso(r.checkedAt) || !validIso(r.startTime)) errors.push(`${r.recordKind}/${r.externalId}: invalid ISO timestamp`);
    if (['yellow', 'orange', 'red'].includes(r.severity) && (!r.statusSource || r.statusSource.official !== true)) {
      errors.push(`${r.recordKind}/${r.externalId}: elevated severity requires statusSource.official === true`);
    }
    if (looksLikeSecret(r.externalId) || looksLikeSecret(r.sourceUrl)) errors.push(`${r.recordKind}/${r.externalId}: field resembles a hardcoded credential and was rejected`);
    if (r.recordKind === 'atmoIndex' && (!Number.isInteger(r.atmoIndex) || r.atmoIndex < 1 || r.atmoIndex > 6)) {
      errors.push(`${r.recordKind}/${r.externalId}: invalid ATMO index value ${r.atmoIndex}`);
    }
  }
  if (r.recordKind === 'pollutionEpisodeSummary' && typeof r.activeEpisodeCount !== 'number') {
    errors.push('pollutionEpisodeSummary missing activeEpisodeCount');
  }
}
if (!sawSourceHealth) warnings.push('No sourceHealth record observed in merged input (upstream fetch may not have run)');

return [{ json: { recordKind: 'validationResult', passed: errors.length === 0, errors, warnings } }, ...allInputs.map((r) => ({ json: r }))];

const config = $items('Set Connector Config')[0].json;
const items = $input.all().map((i) => i.json || {});
const validation = items.find((i) => i.recordKind === 'validationResult') || { passed: true, errors: [], warnings: [] };
const atmoIndex = items.filter((i) => i.recordKind === 'atmoIndex');
const pollutionEpisodes = items.filter((i) => i.recordKind === 'pollutionEpisode');
const episodeSummary = items.find((i) => i.recordKind === 'pollutionEpisodeSummary') || { activeEpisodeCount: pollutionEpisodes.length, zeroActiveEpisodes: pollutionEpisodes.length === 0 };
const zones = items.filter((i) => i.recordKind === 'corridorZone' && !i.zeroZones);
const sourceHealth = items.filter((i) => i.recordKind === 'sourceHealth');

const anyBlocked = sourceHealth.some((h) => h.status === 'credentials_blocked');
const anyFailed = sourceHealth.some((h) => h.status === 'failed');
const allFailed = sourceHealth.length > 0 && sourceHealth.every((h) => h.status === 'failed');
const status = anyBlocked ? 'credentials_blocked' : (!validation.passed ? 'failed' : allFailed ? 'failed' : anyFailed ? 'degraded' : 'ok');

const combined = {
  connectorId: config.connectorId,
  connectorNumber: config.connectorNumber,
  connectorName: config.connectorName,
  workflowName: 'v0001.03_AirQualityConnector',
  workflowVersion: config.workflowVersion,
  generatedAt: config.generatedAt,
  timezone: config.timezone,
  status,
  sources: [
    { sourceId: 'atmo-france', sourceName: 'Atmo France / Atmo Data', endpoint: config.atmoBaseUrl + config.atmoIndicesPath, category: 'air_quality' },
    { sourceId: 'atmo-france-episodes', sourceName: 'Atmo France / Atmo Data (pollution episodes)', endpoint: config.atmoBaseUrl + config.atmoEpisodesPath, category: 'pollution_episode' },
  ],
  atmoIndex,
  pollutionEpisodes,
  pollutionEpisodeSummary: { activeEpisodeCount: episodeSummary.activeEpisodeCount, zeroActiveEpisodes: episodeSummary.zeroActiveEpisodes },
  zones,
  records: [...atmoIndex, ...pollutionEpisodes],
  sourceHealth,
  attribution: { required: true, license: 'ODbL', source: 'Atmo France / Atmo Data' },
  validation: { passed: validation.passed, errors: validation.errors || [], warnings: validation.warnings || [] },
  compatibility: {
    targetMonitoringFeed: 'public/cdm-monitoring-status.json',
    targetMapFeed: 'public/data/atmo-air-quality-map.json',
    mode: 'compatibility_candidate',
  },
};

function emit(path, payload, label) {
  return { json: { targetPath: path, label, jsonText: JSON.stringify(payload, null, 2) + '\n' } };
}

const atmoIndexFeed = { generatedAt: config.generatedAt, source: 'atmo-france', observations: atmoIndex };
const episodesFeed = { generatedAt: config.generatedAt, source: 'atmo-france-episodes', activeEpisodeCount: episodeSummary.activeEpisodeCount, observations: pollutionEpisodes };
const zonesFeed = { generatedAt: config.generatedAt, corridorKm: Number(config.corridorKm), corridorZoneCount: zones.length, zones };
const healthFeed = { generatedAt: config.generatedAt, sources: sourceHealth };
const compatMonitoringFeed = { generatedAt: config.generatedAt, sourceStatus: sourceHealth, alerts: [...atmoIndex, ...pollutionEpisodes] };
const compatMapFeed = {
  schemaVersion: 1,
  generatedAt: config.generatedAt,
  maxAgeHours: Math.round(Number(config.staleAfterMinutes) / 60),
  source: 'Atmo France and regional AASQA',
  license: 'ODbL',
  attribution: config.attributionText,
  palette: { '1': '#50f0e6', '2': '#50ccaa', '3': '#f0e641', '4': '#ff5050', '5': '#960032', '6': '#7d2181' },
  markers: zones,
};

return [
  emit(config.outputDirectory + '/air-quality-connector-output.json', combined, 'air-quality-connector-output'),
  emit(config.outputDirectory + '/air-quality-atmo-index.normalized.json', atmoIndexFeed, 'air-quality-atmo-index.normalized'),
  emit(config.outputDirectory + '/air-quality-pollution-episodes.normalized.json', episodesFeed, 'air-quality-pollution-episodes.normalized'),
  emit(config.outputDirectory + '/air-quality-zones.normalized.json', zonesFeed, 'air-quality-zones.normalized'),
  emit(config.outputDirectory + '/air-quality-source-health.json', healthFeed, 'air-quality-source-health'),
  emit(config.outputDirectory + '/air-quality-monitoring-status.compat.json', compatMonitoringFeed, 'air-quality-monitoring-status.compat'),
  emit(config.outputDirectory + '/atmo-air-quality-map.compat.json', compatMapFeed, 'atmo-air-quality-map.compat'),
];

const output = [];
for (const item of $input.all()) {
  const buf = Buffer.from(item.json.jsonText, 'utf8');
  const fileName = String(item.json.targetPath).split('/').pop();
  const binary = await this.helpers.prepareBinaryData(buf, fileName, 'application/json');
  output.push({ json: item.json, binary: { data: binary } });
}
return output;

const LABELS = new Set(['air-quality-connector-output', 'air-quality-atmo-index.normalized', 'air-quality-pollution-episodes.normalized', 'air-quality-zones.normalized', 'air-quality-source-health', 'air-quality-monitoring-status.compat', 'atmo-air-quality-map.compat']);
const results = [];
for (const item of $input.all()) {
  const targetPath = (item.json && item.json.targetPath) || 'unknown';
  const fileName = String(targetPath).split('/').pop() || 'unknown';
  const label = fileName.replace(/\.json$/, '');
  if (!item.binary || !item.binary.data) {
    results.push({ json: { label, targetPath, validJson: false, bytes: 0, error: 'No binary data read back for ' + fileName } });
    continue;
  }
  const text = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch (err) {
    results.push({ json: { label, targetPath, validJson: false, bytes: Buffer.byteLength(text, 'utf8'), error: 'Invalid JSON: ' + err.message } });
    continue;
  }
  let shapeError = null;
  if (label === 'air-quality-connector-output' && (!parsed.connectorId || !Array.isArray(parsed.sourceHealth) || !parsed.validation)) {
    shapeError = 'air-quality-connector-output missing connectorId, sourceHealth[], or validation';
  }
  if (label === 'air-quality-source-health' && !Array.isArray(parsed.sources)) {
    shapeError = 'air-quality-source-health missing sources[]';
  }
  if (!LABELS.has(label)) shapeError = shapeError || ('Unexpected output label: ' + label);
  results.push({ json: { label, targetPath, validJson: !shapeError, bytes: Buffer.byteLength(text, 'utf8'), error: shapeError } });
}
return results;

const config = $items('Set Connector Config')[0].json;
const validationResults = $input.all().map((i) => i.json || {});
const generatedAt = config.generatedAt || new Date().toISOString();
const completedAt = new Date().toISOString();
const failures = validationResults.filter((r) => r.validJson !== true || r.error);
const errors = failures.map((f) => ({ label: f.label, targetPath: f.targetPath, message: f.error || 'Output file did not pass validation' }));

return [{
  json: {
    recordKind: 'runDiagnostics',
    ok: errors.length === 0,
    connectorId: config.connectorId,
    workflowVersion: config.workflowVersion,
    generatedAt,
    completedAt,
    validationStatus: errors.length === 0 ? 'passed' : 'failed',
    writeStatus: validationResults.length > 0 ? 'attempted' : 'not_attempted',
    infraBlocked: false,
    outputFilenames: validationResults.map((r) => r.targetPath).filter(Boolean),
    errors,
    warnings: [],
    note: 'If Atmo Login / Fetch Token fails with 401/403, classify as CREDENTIALS_BLOCKED. If Write Air Quality Output Files or Read Back Air Quality Output Files fail upstream with a file-access error rather than reaching this node, classify the run as INFRA_BLOCKED_AT_OUTPUT_WRITE, not FAILED.',
  },
}];
